/* C evaluation fixture for the bounded polyhedral optimizer. */
long kernel(long seed){double a[1024],b[1024],c[1024];for(long i=0;i<32;i++)for(long j=0;j<32;j++){a[i*32+j]=(i+j+seed)&15;b[i*32+j]=(i*3+j)&7;c[i*32+j]=0;}for(long i=0;i<32;i++)for(long j=0;j<32;j++)for(long k=0;k<32;k++)c[i*32+j]+=a[i*32+k]*b[j*32+k];long sum=0;for(long i=0;i<32;i++)for(long j=0;j<32;j++)sum+=(long)c[i*32+j]*(i+j+1);return sum;}
